    public static function svg(string $name, string $class = 'mx-ico'): string
    {
        $name = strtolower(trim($name));
        $p = self::PATHS[$name] ?? self::PATHS['sparkles'];
        $fill = $name === 'quote' ? 'currentColor' : 'none';
        return '<svg class="' . htmlspecialchars($class) . '" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" fill="' . $fill . '" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $p . '</svg>';
    }

    /** @return list<string> */
    public static function names(): array
    {
        return array_keys(self::PATHS);
    }
